    async def get_agent_violations_all(self, agent_id: str, *, limit: Optional[int] = None, cursor: Optional[str] = None, request_options: Optional[RequestOptions] = None) -> AsyncIterator[_m.ConstitutionViolation]:
        """Every item `get_agent_violations` returns, following the `cursor` cursor until the server
        reports no further pages. Starts at `cursor` when one is given.
        """
        guard = _CursorGuard()
        while True:
            page = await self.get_agent_violations(agent_id, limit=limit, cursor=cursor, request_options=request_options)
            items = page.violations or []
            for item in items:
                yield item

            cursor = guard.advance(page.cursor, page.has_more, not items)
            if cursor is None:
                return

